use super::*;
use semio_framework_os_kernel::{sqlite_snapshot::*,ArtifactSqliteSnapshot};
fn fixture()->BitmapSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();BitmapSnapshot{schema:f["schema"].as_str().unwrap().into(),seed:f["seed"].as_str().unwrap().parse().unwrap(),input:BitmapInput{width:f["input"]["width"].as_u64().unwrap() as u32,height:f["input"]["height"].as_u64().unwrap() as u32,palette:f["input"]["palette"].as_array().unwrap().iter().map(|c|BitmapColor{r:c["r"].as_u64().unwrap() as u32,g:c["g"].as_u64().unwrap() as u32,b:c["b"].as_u64().unwrap() as u32,a:c["a"].as_u64().unwrap() as u32}).collect(),pixels:f["input"]["pixels"].as_str().unwrap().into()},output:BitmapOutputSpec{width:f["output"]["width"].as_u64().unwrap() as u32,height:f["output"]["height"].as_u64().unwrap() as u32,periodic:true},model:BitmapOverlappingModel{pattern_size:u32::MAX,symmetry:8,periodic_input:false,ground:Some(u32::MAX)},pinned:vec![BitmapPinnedPixel{x:u32::MAX,y:1,color:u32::MAX},BitmapPinnedPixel{x:0,y:0,color:0}]}}
fn project(s:&BitmapSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<BitmapSnapshot,String>{BitmapSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_wfc_bitmap_all_native_fields(){let s=fixture();let d=project(&s);assert_eq!(d.tables.len(),6);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(actual,s);assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&s));assert_eq!(store::ArtifactDsl::print_dsl(&actual),store::ArtifactDsl::print_dsl(&s));let mut arbitrary=s;arbitrary.input.pixels="invalid native scalar 🧬".into();arbitrary.input.palette.clear();arbitrary.model.ground=None;assert_eq!(restore(&project(&arbitrary)).unwrap(),arbitrary);}
#[test]fn sqlite_snapshot_wfc_bitmap_independent_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let s=fixture();let bytes=export_sqlite_database(&project(&s),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const p=d.query('SELECT red,palette_indices_base64 FROM wfc_bitmap_palette JOIN wfc_bitmap_input ON document_id=wfc_bitmap_input.id ORDER BY ordinal').all();if(p.length!==2||p[0].red!==4294967295||p[0].palette_indices_base64!=='AAE=')throw Error('fields');d.query('UPDATE wfc_bitmap_pin SET x=7 WHERE ordinal=1').run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let mut expected=s;expected.pinned[1].x=7;assert_eq!(restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap(),expected);}
#[test]fn sqlite_snapshot_wfc_bitmap_invalid_relations_limits_cancellation(){let d=project(&fixture());for n in 0..5{let mut m=d.clone();match n{0=>m.table_mut("wfc_bitmap_pin").unwrap().rows[0].values[1]=SqliteValue::Integer(2),1=>m.table_mut("wfc_bitmap_palette").unwrap().rows[0].values[2]=SqliteValue::Integer(9),2=>m.table_mut("wfc_bitmap_output").unwrap().rows[0].values[3]=SqliteValue::Integer(2),3=>m.table_mut("wfc_bitmap_model").unwrap().rows[0].values[1]=SqliteValue::Integer(-1),_=>m.table_mut("wfc_bitmap_document").unwrap().rows[0].values[2]=SqliteValue::Text("01".into())};assert!(restore(&m).is_err());}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(BitmapSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()})).is_err());let mut s=fixture();s.input.pixels="x".repeat(100000);assert!(s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::ProjectSnapshot||p.completed==0,SqliteDatabaseLimits::default())).is_err());}
#[test]fn sqlite_snapshot_wfc_bitmap_actual_owner_native_admission(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=(provider.import)("bitmap",&dialect,project(&s),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}let invalid=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&invalid,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}

#[test]fn sqlite_snapshot_bitmap_declared_erased_roundtrip_both_native_encodings(){let source=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let schema=codec.schema.clone();let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<BitmapSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<BitmapSnapshot as store::ArtifactDsl>::print_dsl(&source))};let d=(provider.export)(&schema,&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;assert_eq!(project(&restore(&d).unwrap()),project(&source));let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let database=import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();assert_eq!((provider.import)(&schema,&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value,payload);}}
#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_bitmap_actual_owned_io_declaration_codec(){use semio_framework_os_kernel::io::{register_native_snapshot_codec,io_mechanism::{io_export_sqlite_snapshot,io_import_sqlite_snapshot}};register_native_snapshot_codec(crate::WFC_BITMAP_DIALECT,crate::standards::v1::subsets::any::io::io().native.codec).unwrap();let source=fixture();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.bitmap".into(),standard:"1".into(),subset:"*".into()};for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let mut phases=Vec::new();let bytes=io_export_sqlite_snapshot(&dialect,&source,encoding,SqliteDatabaseLimits::default(),&mut |p|{phases.push(p.phase);true}).await.unwrap().value;let back=io_import_sqlite_snapshot::<BitmapSnapshot>(&dialect,&bytes,SqliteDatabaseLimits::default(),&mut |_|true).await.unwrap().value;assert_eq!(project(&back),project(&source));assert!(!phases.iter().any(|p|matches!(p,SqliteSnapshotPhase::DecodeNative|SqliteSnapshotPhase::EncodeNative)));}}

#[test]
fn sqlite_snapshot_bitmap_explicit_controlled_native_owner(){
 let source=fixture();for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<BitmapSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<BitmapSnapshot as store::ArtifactDsl>::print_dsl(&source))};let actual=BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(actual,source);assert!(BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}
}

#[test]
fn sqlite_snapshot_bitmap_controlled_native_interior_and_large_copy(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let n=f["controlledAdmission"]["collectionItems"].as_u64().unwrap() as usize;let cancel=f["controlledAdmission"]["cancelAfter"].as_u64().unwrap() as usize;let mut source=fixture();source.input.palette=vec![source.input.palette[0].clone();n];source.pinned=vec![source.pinned[0].clone();n];for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<BitmapSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<BitmapSnapshot as store::ArtifactDsl>::print_dsl(&source))};assert_eq!(BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),source);let mut interior=false;let error=BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==n&&p.completed==cancel{interior=true;false}else{true}},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior);assert!(error.contains("canceled"));}
 source.input.pixels="x".repeat(f["controlledAdmission"]["largeTextBytes"].as_u64().unwrap() as usize);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(<BitmapSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(<BitmapSnapshot as store::ArtifactDsl>::print_dsl(&source))};assert!(BitmapSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["controlledAdmission"]["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());}
}

#[test]
fn sqlite_snapshot_bitmap_explicit_controlled_native_output(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let state=&f["ownedSparseState"];let mut sparse=fixture();sparse.schema=state["schema"].as_str().unwrap().into();sparse.input.pixels=state["pixels"].as_str().unwrap().into();assert!(state["ground"].is_null());assert!(state["palette"].as_array().unwrap().is_empty());assert!(state["pinned"].as_array().unwrap().is_empty());sparse.input.palette.clear();sparse.pinned.clear();sparse.model.ground=None;
 for source in[fixture(),BitmapSnapshot::default(),sparse]{
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let expected=match encoding{SnapshotEncoding::Binary=>store::io_schema::IoPayload::Binary(store::ArtifactPack::encode_pack(&source)),SnapshotEncoding::Text=>store::io_schema::IoPayload::Text(store::ArtifactDsl::print_dsl(&source))};
  assert_eq!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
  assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
  assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
 }
 }
}

#[test]
fn sqlite_snapshot_bitmap_output_real_collection_and_unicode_frontiers(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();
 let n=f["controlledAdmission"]["collectionItems"].as_u64().unwrap() as usize;
 let cancel=f["controlledAdmission"]["cancelAfter"].as_u64().unwrap() as usize;
 let bytes=f["controlledAdmission"]["largeTextBytes"].as_u64().unwrap() as usize;
 let mut source=fixture();source.input.palette=vec![source.input.palette[0].clone();n];source.pinned=vec![source.pinned[0].clone();n];
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let mut interior=false;
  let error=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total==n&&p.completed==cancel{interior=true;false}else{true}},SqliteDatabaseLimits::default())).unwrap_err();
  assert!(interior);assert!(error.contains("canceled"));
  assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_rows:2*n+3,..SqliteDatabaseLimits::default()})).is_err());
 }
 source.input.pixels="🧬".repeat(bytes/4);
 for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
  let mut interior=false;
  let error=source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::EncodeNative&&p.total>=65536&&p.completed>=65536&&p.completed<p.total{interior=true;false}else{true}},SqliteDatabaseLimits::default())).unwrap_err();
  assert!(interior);assert!(error.contains("canceled"));
  assert!(source.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:f["controlledAdmission"]["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());
 }
}
